command:
$ErrorActionPreference = "Stop"
git fetch origin main work/validation-churn-guards --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "9549dae8ad20191eb7454f724a8f4e19ca9d7bdc") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout work/validation-churn-guards
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/validation-churn-guards
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }
python -X utf8 tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "focused remote workflow contract failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "VALIDATION_CHURN_GUARDS_PREMAIN_PASS"
